fn putDouble(outp:[*]u8,x:f64)void{const bits=@as(u64,@bitCast(x));for(0..8)|k|outp[k]=@truncate(bits>>(8*k));}
export fn orbital_transfer_work(v:[*]const i64,n:usize,outp:[*]u8,cap:usize)i64{if(n!=4)return -1;const a=v[0];const b=v[1];const r1=v[2];const r2=v[3];if(a < -1000000000 or a>1000000000 or b < -1000000 or b>1000000 or r1<1 or r1>1000000000 or r2<1 or r2>1000000000)return -1;if(cap<8)return -2;const work=(6.67430e-11*@as(f64,@floatFromInt(a))*@as(f64,@floatFromInt(b))/2.0)*(1.0/@as(f64,@floatFromInt(r1))-1.0/@as(f64,@floatFromInt(r2)));putDouble(outp,work);return 8;}
